from pathlib import Path
import hashlib
import json

def write_file_checked(path, content):
    path = Path(path)
    path.write_text(content, encoding='utf-8', newline='\n')
    payload = {
        'path': str(path),
        'size_bytes': path.stat().st_size,
        'sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
    }
    print(json.dumps(payload, sort_keys=True))

write_file_checked('kaggle_path_safety.py', 'from __future__ import annotations\n\nfrom contextlib import contextmanager\nfrom pathlib import Path\nfrom typing import Iterator\n\n\nOUTPUT_PATH_FIELDS = {\n    "token_output",\n    "token_manifest_path",\n    "train_manifest_path",\n    "calibrated_eval_path",\n    "parent_calibration_report_path",\n    "candidate_decision_path",\n    "submission_zip_path",\n    "package_output_path",\n}\n\nOUTPUT_DIR_FIELDS = {\n    "token_output_dir",\n    "output_adapter_dir",\n    "eval_output_dir",\n    "stage_log_dir",\n}\n\nPACKAGE_FIELDS = {"submission_zip_path", "package_output_path"}\n\n\ndef is_under_path(path: Path, parent: Path) -> bool:\n    try:\n        resolved_path = Path(path).resolve(strict=False)\n        resolved_parent = Path(parent).resolve(strict=False)\n    except OSError:\n        resolved_path = Path(str(path)).absolute()\n        resolved_parent = Path(str(parent)).absolute()\n    try:\n        resolved_path.relative_to(resolved_parent)\n        return True\n    except ValueError:\n        return False\n\n\ndef is_kaggle_input_path(path: Path) -> bool:\n    return is_under_path(Path(path), Path("/kaggle/input"))\n\n\ndef is_kaggle_working_path(path: Path) -> bool:\n    return is_under_path(Path(path), Path("/kaggle/working"))\n\n\ndef _looks_like_kaggle_absolute(path: Path) -> bool:\n    return path.is_absolute() and str(path).replace("\\\\", "/").startswith("/kaggle/")\n\n\ndef require_not_kaggle_input_path(path: str | Path, *, field_name: str) -> Path:\n    candidate = Path(path)\n    if is_kaggle_input_path(candidate):\n        raise SystemExit(f"{field_name} must not write under /kaggle/input: {candidate}")\n    return candidate\n\n\ndef require_writable_output_path(\n    path: str | Path,\n    *,\n    field_name: str,\n    must_be_under_working_when_kaggle: bool = True,\n    allow_tmp_runtime_patch: bool = False,\n) -> Path:\n    candidate = require_not_kaggle_input_path(path, field_name=field_name)\n    normalized = str(candidate).replace("\\\\", "/")\n    if (candidate.is_absolute() and is_under_path(candidate, Path("/tmp")) or normalized.startswith("/tmp/") or normalized == "/tmp") and not allow_tmp_runtime_patch:\n        raise SystemExit(f"{field_name} must not use /tmp for training/eval outputs: {candidate}")\n    if must_be_under_working_when_kaggle and _looks_like_kaggle_absolute(candidate) and not is_kaggle_working_path(candidate):\n        raise SystemExit(f"{field_name} must be under /kaggle/working on Kaggle: {candidate}")\n    return candidate\n\n\ndef require_writable_output_dir(\n    path: str | Path,\n    *,\n    field_name: str,\n    must_be_under_working_when_kaggle: bool = True,\n    allow_tmp_runtime_patch: bool = False,\n) -> Path:\n    return require_writable_output_path(\n        path,\n        field_name=field_name,\n        must_be_under_working_when_kaggle=must_be_under_working_when_kaggle,\n        allow_tmp_runtime_patch=allow_tmp_runtime_patch,\n    )\n\n\ndef require_safe_config_output_paths(\n    config: dict,\n    *,\n    stage: str | None = None,\n    allow_submission_artifact: bool = False,\n) -> dict:\n    for field in sorted(OUTPUT_PATH_FIELDS):\n        value = config.get(field)\n        if value in (None, ""):\n            continue\n        if field in PACKAGE_FIELDS and not allow_submission_artifact:\n            raise SystemExit(f"{field} is forbidden in active Day 1.2 config: {value}")\n        require_writable_output_path(value, field_name=field)\n    for field in sorted(OUTPUT_DIR_FIELDS):\n        value = config.get(field)\n        if value in (None, ""):\n            continue\n        require_writable_output_dir(value, field_name=field)\n    return config\n\n\ndef safe_mkdir_for_output(path: str | Path, *, field_name: str) -> Path:\n    directory = require_writable_output_dir(path, field_name=field_name)\n    directory.mkdir(parents=True, exist_ok=True)\n    return directory\n\n\ndef safe_write_text(path: str | Path, content: str, *, field_name: str, encoding: str = "utf-8") -> Path:\n    target = require_writable_output_path(path, field_name=field_name)\n    target.parent.mkdir(parents=True, exist_ok=True)\n    target.write_text(content, encoding=encoding)\n    return target\n\n\n@contextmanager\ndef safe_open_text_for_write(\n    path: str | Path,\n    *,\n    field_name: str,\n    encoding: str = "utf-8",\n    newline: str | None = None,\n) -> Iterator:\n    target = require_writable_output_path(path, field_name=field_name)\n    target.parent.mkdir(parents=True, exist_ok=True)\n    with target.open("w", encoding=encoding, newline=newline) as handle:\n        yield handle\n')
write_file_checked('kaggle_runtime_patches.py', 'from __future__ import annotations\n\nimport os\nfrom pathlib import Path\nimport shutil\nimport stat\nimport sys\nfrom typing import Iterable\n\nfrom kaggle_path_safety import require_not_kaggle_input_path\n\n\nCUTLASS_PATH = Path("/kaggle/usr/lib/notebooks/ryanholbrook/nvidia-utility-script/nvidia_cutlass_dsl/python_packages")\nPTXAS_BLACKWELL_PATH = Path("/kaggle/usr/lib/notebooks/ryanholbrook/nvidia-utility-script/triton/backends/nvidia/bin/ptxas-blackwell")\nPTXAS_WORKING_PATH = Path("/tmp/ptxas-blackwell")\n\n\ndef patch_cutlass_path() -> dict:\n    exists = CUTLASS_PATH.exists()\n    if exists and str(CUTLASS_PATH) not in sys.path:\n        sys.path.insert(0, str(CUTLASS_PATH))\n    return {"cutlass_path": str(CUTLASS_PATH), "cutlass_path_exists": exists, "cutlass_path_inserted": exists}\n\n\ndef patch_ptxas_blackwell() -> dict:\n    if not PTXAS_BLACKWELL_PATH.exists():\n        return {"ptxas_source": str(PTXAS_BLACKWELL_PATH), "ptxas_source_exists": False, "ptxas_patched": False}\n    shutil.copy2(PTXAS_BLACKWELL_PATH, PTXAS_WORKING_PATH)\n    PTXAS_WORKING_PATH.chmod(stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)\n    os.environ["TRITON_PTXAS_PATH"] = str(PTXAS_WORKING_PATH)\n    os.environ["TRITON_PTXAS_BLACKWELL_PATH"] = str(PTXAS_WORKING_PATH)\n    return {\n        "ptxas_source": str(PTXAS_BLACKWELL_PATH),\n        "ptxas_working_path": str(PTXAS_WORKING_PATH),\n        "ptxas_source_exists": True,\n        "ptxas_patched": True,\n    }\n\n\ndef apply_runtime_patches() -> dict:\n    report = {}\n    report.update(patch_cutlass_path())\n    report.update(patch_ptxas_blackwell())\n    return report\n\n\ndef normalize_optional_path(value) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    if not text or text.lower() in {"none", "null", "false"}:\n        return None\n    return text\n\n\ndef require_real_optional_path(value, *, field_name: str) -> str | None:\n    text = normalize_optional_path(value)\n    if text is None:\n        return None\n    if text == "auto_or_none":\n        raise SystemExit(f"{field_name} must not be auto_or_none")\n    if not Path(text).exists():\n        raise SystemExit(f"{field_name} does not exist: {text}")\n    return text\n\n\ndef discover_parent_adapter(search_roots: Iterable[str | Path] = ("/kaggle/input", "/kaggle/working")) -> str | None:\n    candidates: list[Path] = []\n    for root in search_roots:\n        base = Path(root)\n        if not base.exists():\n            continue\n        for config_path in base.rglob("adapter_config.json"):\n            adapter_dir = config_path.parent\n            if (adapter_dir / "adapter_model.safetensors").exists():\n                candidates.append(adapter_dir)\n    if not candidates:\n        return None\n    def score(path: Path) -> tuple[int, str]:\n        text = str(path).lower()\n        preferred = any(token in text for token in ("nemotron-adapter", "tinker", "huikang", "parent"))\n        return (1 if preferred else 0, str(path))\n    return str(sorted(candidates, key=score, reverse=True)[0])\n\n\ndef patch_yaml_value(path: str | Path, key: str, value: str) -> None:\n    yaml_path = require_not_kaggle_input_path(path, field_name="config_patch_path")\n    lines = yaml_path.read_text(encoding="utf-8").splitlines()\n    replaced = False\n    out = []\n    for line in lines:\n        if line.strip().startswith(f"{key}:"):\n            out.append(f"{key}: {value}")\n            replaced = True\n        else:\n            out.append(line)\n    if not replaced:\n        out.append(f"{key}: {value}")\n    yaml_path.write_text("\\n".join(out) + "\\n", encoding="utf-8")\n\n\ndef ensure_parent_adapter_in_config(config_path: str | Path, config: dict) -> str:\n    current = normalize_optional_path(config.get("parent_adapter_path"))\n    if current and current != "auto_or_none":\n        require_real_optional_path(current, field_name="parent_adapter_path")\n        return current\n    discovered = discover_parent_adapter()\n    if not discovered:\n        raise SystemExit("parent_adapter_path is none and no parent adapter was discovered under /kaggle/input or /kaggle/working")\n    patch_yaml_value(config_path, "parent_adapter_path", discovered)\n    config["parent_adapter_path"] = discovered\n    return discovered\n')
write_file_checked('kaggle_backend_probe.py', 'from __future__ import annotations\n\nimport importlib.util\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nfrom typing import Any\nimport zipfile\n\nfrom kaggle_runtime_patches import apply_runtime_patches\nfrom kaggle_path_safety import require_writable_output_path, safe_write_text\n\n\nDEFAULT_BASE_MODEL_PATHS = (\n    "/kaggle/input/models/metric/nemotron-3-nano-30b-a3b-bf16/transformers/default/1",\n    "/kaggle/input/nemotron-3-nano-30b-a3b-bf16",\n)\n\n\ndef has_module(name: str) -> bool:\n    return importlib.util.find_spec(name) is not None\n\n\ndef detect_cuda() -> dict[str, Any]:\n    if not has_module("torch"):\n        return {"torch_import": False, "cuda_available": False, "gpu_name": None}\n    import torch\n\n    available = bool(torch.cuda.is_available())\n    return {\n        "torch_import": True,\n        "cuda_available": available,\n        "gpu_name": torch.cuda.get_device_name(0) if available else None,\n    }\n\n\ndef detect_lora_request() -> bool:\n    if not has_module("vllm"):\n        return False\n    try:\n        from vllm.lora.request import LoRARequest  # noqa: F401\n    except Exception:\n        return False\n    return True\n\n\ndef detect_anti086_input_root(base: str | Path = "/kaggle/input") -> str | None:\n    base_path = Path(base)\n    if not base_path.exists():\n        return None\n    required_sets = (\n        {"curriculum_manifest.json"},\n        {"win_corpus_manifest.json"},\n        {"solver_coverage_report.json", "win_micro.jsonl"},\n    )\n    for path in sorted(base_path.rglob("*")):\n        if path.is_dir() and any(all((path / name).exists() for name in required) for required in required_sets):\n            return str(path)\n        if path.name in {"anti086_kaggle_input.zip", "win_system_kaggle_input.zip"}:\n            return str(path)\n    return None\n\n\ndef detect_parent_adapter(base: str | Path = "/kaggle/input") -> str | None:\n    base_path = Path(base)\n    if not base_path.exists():\n        return None\n    for config in sorted(base_path.rglob("adapter_config.json")):\n        if (config.parent / "adapter_model.safetensors").exists():\n            return str(config.parent)\n    return None\n\n\ndef probe_backend(\n    *,\n    base_model_path: str | None = None,\n    input_base: str | Path = "/kaggle/input",\n    output_path: str | Path = "/kaggle/working/anti086_backend_probe.json",\n) -> dict[str, Any]:\n    runtime_patch = apply_runtime_patches()\n    cuda = detect_cuda()\n    vllm_available = has_module("vllm")\n    cutlass_root = Path("/kaggle/usr/lib/notebooks/ryanholbrook/nvidia-utility-script/nvidia_cutlass_dsl/python_packages")\n    ptxas = Path("/kaggle/usr/lib/notebooks/ryanholbrook/nvidia-utility-script/triton/backends/nvidia/bin/ptxas-blackwell")\n    selected_base = base_model_path or next((p for p in DEFAULT_BASE_MODEL_PATHS if Path(p).exists()), DEFAULT_BASE_MODEL_PATHS[0])\n    anti086_root = detect_anti086_input_root(input_base)\n    report = {\n        "platform": platform.platform(),\n        "cuda_visible_devices": os.environ.get("CUDA_VISIBLE_DEVICES"),\n        **cuda,\n        "transformers_import": has_module("transformers"),\n        "peft_import": has_module("peft"),\n        "vllm_import": vllm_available,\n        "lora_request_import": detect_lora_request(),\n        "cutlass_path_exists": cutlass_root.exists(),\n        "ptxas_blackwell_path_exists": ptxas.exists(),\n        "base_model_path": selected_base,\n        "base_model_path_exists": Path(selected_base).exists(),\n        "anti086_input_root": anti086_root,\n        "win_input_root": anti086_root,\n        "anti086_input_root_exists": anti086_root is not None,\n        "parent_adapter_path": detect_parent_adapter(input_base),\n        "runtime_patch": runtime_patch,\n        "micro_stack_test_label": "INFRASTRUCTURE STACK TEST ONLY - NOT A 0.95 CANDIDATE - NOT MAIN TRAINING - NOT SUBMISSION READY",\n    }\n    if report["cuda_available"] and report["transformers_import"] and report["peft_import"] and report["base_model_path_exists"] and report["anti086_input_root_exists"]:\n        report["recommended_mode"] = "BACKEND_OK_FOR_MICRO" if report["vllm_import"] and report["lora_request_import"] else "BACKEND_NO_VLLM_BUT_TRAIN_POSSIBLE"\n    else:\n        report["recommended_mode"] = "BACKEND_NOT_SAFE"\n    out = require_writable_output_path(output_path, field_name="backend_probe_output_path")\n    safe_write_text(out, json.dumps(report, sort_keys=True, indent=2), field_name="backend_probe_output_path")\n    return report\n\n\ndef main() -> None:\n    report = probe_backend()\n    print(json.dumps(report, sort_keys=True, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n')
